-- Shopify México (20261109000100 + 20261109000200) — database tests (STAGING). One transaction, ROLLED BACK.
-- Catalog: supabase/staging/data_shopify_mx_catalogo.sql (generated by scripts/f360/shopify_catalog.mjs from the real store).
BEGIN;
-- @include supabase/migrations/20261109000200_f360_shopify_link_by_name.sql
CREATE TEMP TABLE t_results (n serial, status text, name text, detail text) ON COMMIT DROP;
CREATE FUNCTION pg_temp.ok(p_cond boolean, p_name text, p_detail text) RETURNS void LANGUAGE sql AS
$$ INSERT INTO t_results(status,name,detail) VALUES (CASE WHEN coalesce(p_cond, false) THEN 'PASS' ELSE 'FAIL' END, p_name, p_detail) $$;
INSERT INTO f360.sales_targets (key, name, kind, base_url, is_production, is_test, active, fulfillment_location_id, stock_policy, orders_mode)
  SELECT 'shopify_mx', 'Shopify México (prueba)', 'shopify', 'https://z9fdqc-0z.myshopify.com', false, false, true, fulfillment_location_id, stock_policy, 'on'
    FROM f360.sales_targets WHERE key = 'woo_staging4';
-- @include supabase/staging/data_shopify_mx_catalogo.sql
DO $$
DECLARE r jsonb; r2 jsonb; loc jsonb; lnk bigint; t uuid; sid bigint; vid uuid; bodega uuid; oh0 int; oh1 int; res jsonb; c f360.commerce_woo_orders; n int;
BEGIN
  SELECT id, fulfillment_location_id INTO t, bodega FROM f360.sales_targets WHERE key = 'shopify_mx';
  PERFORM pg_temp.ok((SELECT count(*) FROM f360.shopify_variants WHERE target_id = t) = 1278, 'catálogo Shopify cargado (1278 variantes)', '');
  r := f360.shopify_link_variants('shopify_mx', 'woo_staging4');
  INSERT INTO t_results(status,name,detail) VALUES ('INFO', 'liga', (r - 'pendientes')::text);
  INSERT INTO t_results(status,name,detail) VALUES ('INFO', 'pendientes', left((r->'pendientes')::text, 1500));
  PERFORM pg_temp.ok((r->>'ligadas')::int = 1278, 'liga automática: las 1278 variantes', r->>'ligadas');
  PERFORM pg_temp.ok(NOT EXISTS (SELECT variant_id FROM f360.woo_variant_links WHERE target_id = t GROUP BY variant_id HAVING count(*) > 1), 'un par de Fuxia 360 ↔ una sola variante Shopify', '');
  PERFORM pg_temp.ok((SELECT bool_and(f360.shopify_norm(pc.name) = f360.shopify_norm(s.color) AND v.size_label = s.size)
                        FROM f360.woo_variant_links l JOIN f360.shopify_variants s ON s.target_id = t AND s.link_id = l.woo_variation_id
                        JOIN f360.product_variants v ON v.id = l.variant_id JOIN f360.product_colors pc ON pc.id = v.color_id WHERE l.target_id = t),
                     'toda liga tiene el mismo color y talla', '');
  r2 := f360.shopify_link_variants('shopify_mx', 'woo_staging4');
  PERFORM pg_temp.ok((r2->>'nuevas')::int = 0 AND r2->>'ligadas' = r->>'ligadas', 'repetir no cambia nada', r2->>'nuevas');
  PERFORM pg_temp.ok((SELECT count(*) FROM f360.woo_variant_links WHERE target_id = (SELECT id FROM f360.sales_targets WHERE key = 'woo_staging4')) = 1302,
                     'las ligas de la tienda Woo no se tocan', '');

  -- A paid Shopify order (already translated to the Woo shape by f360-shopify) moves Bodega stock like a Woo order.
  SELECT s.shopify_variant_id, l.variant_id INTO sid, vid FROM f360.woo_variant_links l JOIN f360.shopify_variants s ON s.target_id = t AND s.link_id = l.woo_variation_id
   WHERE l.target_id = t LIMIT 1;
  -- f360-shopify sends Shopify's ids; localize swaps them for Fuxia 360's link ids (an unknown variant gets none).
  loc := public.f360_shopify_localize('shopify_mx', jsonb_build_object('id', 6612345678901, 'line_items', jsonb_build_array(
    jsonb_build_object('id', 111, 'product_id', 1, 'variation_id', sid, 'quantity', 1), jsonb_build_object('id', 112, 'variation_id', 99999999999999, 'quantity', 1))));
  PERFORM pg_temp.ok((loc->'line_items'->0->>'variation_id')::int = (SELECT link_id FROM f360.shopify_variants WHERE target_id = t AND shopify_variant_id = sid)
                     AND (loc->'line_items'->0->>'shopify_variant_id')::bigint = sid AND loc->'line_items'->1->'variation_id' = 'null'::jsonb,
                     'ids de Shopify → ids internos (variante desconocida: ninguno)', loc::text);
  lnk := (loc->'line_items'->0->>'variation_id')::bigint;
  INSERT INTO f360.inventory_balances (variant_id, location_id, on_hand) VALUES (vid, bodega, 3)
    ON CONFLICT (variant_id, location_id) DO UPDATE SET on_hand = 3;
  oh0 := 3;
  res := public.f360_ingest_woo_order('shopify_mx', jsonb_build_object('delivery_id', 'wh-1', 'topic', 'order.updated'),
    jsonb_build_object('id', 6612345678901, 'status', 'processing', 'date_modified_gmt', '2026-11-09T16:25:00', 'currency', 'MXN', 'refunds', '[]'::jsonb,
      'line_items', jsonb_build_array(jsonb_build_object('id', 111, 'product_id', 1, 'variation_id', lnk, 'sku', 'X', 'quantity', 1))));
  SELECT on_hand INTO oh1 FROM f360.inventory_balances WHERE variant_id = vid AND location_id = bodega;
  PERFORM pg_temp.ok(res->>'result' = 'applied' AND oh1 = oh0 - 1, 'pedido pagado de Shopify descuenta 1 par de Bodega', res::text || ' on_hand=' || oh1);
  res := public.f360_ingest_woo_order('shopify_mx', jsonb_build_object('delivery_id', 'wh-1', 'topic', 'order.updated'),
    jsonb_build_object('id', 6612345678901, 'status', 'processing', 'date_modified_gmt', '2026-11-09T16:25:00', 'currency', 'MXN', 'refunds', '[]'::jsonb,
      'line_items', jsonb_build_array(jsonb_build_object('id', 111, 'product_id', 1, 'variation_id', lnk, 'sku', 'X', 'quantity', 1))));
  SELECT on_hand INTO oh1 FROM f360.inventory_balances WHERE variant_id = vid AND location_id = bodega;
  PERFORM pg_temp.ok(oh1 = oh0 - 1, 'el mismo aviso dos veces no descuenta dos veces', res->>'result');

  res := public.f360_capture_order_economics('shopify_mx', jsonb_build_object('id', 6612345678901, 'status', 'processing', 'created_via', 'checkout',
      'date_created_gmt', '2026-11-09T16:21:00', 'date_paid_gmt', '2026-11-09T16:21:05', 'date_modified_gmt', '2026-11-09T16:25:00', 'currency', 'MXN',
      'prices_include_tax', true, 'discount_total', '280.00', 'discount_tax', '0.00', 'shipping_total', '0.00', 'shipping_tax', '0.00', 'cart_tax', '347.59',
      'total', '2520.00', 'total_tax', '347.59', 'fees_total', 0, 'fees_tax', 0, 'coupon_count', 1, 'payment_method', 'shopify_payments', 'woo_customer_id', 7788,
      'billing_country', 'MX', 'refunds', '[]'::jsonb, 'attribution', NULL,
      'line_items', jsonb_build_array(jsonb_build_object('id', 111, 'product_id', 1, 'variation_id', lnk, 'sku', 'X', 'quantity', 1,
        'subtotal', '2800.00', 'subtotal_tax', '347.59', 'total', '2520.00', 'total_tax', '347.59'))), 'webhook');
  SELECT * INTO c FROM f360.commerce_woo_orders WHERE target_id = t AND woo_order_id = 6612345678901;
  PERFORM pg_temp.ok(c.market = 'MX' AND c.payment_category = 'card' AND c.ever_paid AND c.order_total = 2520,
                     'venta Shopify: México, tarjeta, pagada, monto real', coalesce(c.market, '?') || ' ' || coalesce(c.payment_category, '?') || ' ' || coalesce(c.order_total::text, '?'));
  PERFORM pg_temp.ok(EXISTS (SELECT 1 FROM f360.commerce_orders o WHERE o.external_ref = 'shopify_mx:6612345678901'), 'aparece en commerce_orders (tablero, Growth)', '');
  PERFORM pg_temp.ok(f360.commerce_payment_category('woo-mercado-pago-custom') = 'card' AND f360.commerce_payment_category('paypal') = 'paypal', 'categorías de Woo sin cambio', '');
  PERFORM pg_temp.ok(NOT has_table_privilege('authenticated', 'f360.shopify_variants', 'SELECT'), 'catálogo Shopify no expuesto', '');
END $$;
SELECT status || ' | ' || name || ' | ' || coalesce(detail, '') FROM t_results ORDER BY n;
ROLLBACK;
